#include <atcoder/lazysegtree>
#include <bits/stdc++.h>
using namespace std;

int op(int a, int b) { return max(a, b); }
int e() { return -1e9; }
int mapping(int f, int x) { return f + x; }
int composition(int f, int g) { return f + g; }
int id() { return 0; }

int main() {
    int n;
    cin >> n;
    vector<int> l(n), r(n);
    for (int i = 0; i < n; ++i) {
        cin >> l[i] >> r[i];
    }
    vector<int> rate(500000, 0);
    iota(rate.begin(), rate.end(), 1);
    atcoder::lazy_segtree<int, op, e, int, mapping, composition, id> seg(rate);
    for (int i = 0; i < n; ++i) {
        auto L = seg.max_right(0, [&](int x) { return x < l[i]; });
        auto R = seg.max_right(0, [&](int x) { return x <= r[i]; });
        seg.apply(L, R, 1);
    }
    int q;
    cin >> q;
    for (int i = 0; i < q; ++i) {
        int x;
        cin >> x;
        x--;
        cout << seg.get(x) << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
int N = 500010;

template <class T> struct fenwick_tree {
    int n;
    vector<T> a;
    fenwick_tree(int m) : n(m), a(m + 1, 0) {}
    void add(int x, T y) {
        x ++;
        while(x <= n) {
            a[x] += y;
            x += x & -x;
        }
    }
    T sum(int x) {
        T r = 0;
        while(x > 0) {
            r += a[x];
            x -= x & -x;
        }
        return r;
    }
    T sum(int x, int y) { // [x, y), 0-indexed
        return sum(y) - sum(x);
    }
    int lower_bound(T x) {
        int id = 0;
        for(int i = __lg(n); i >= 0; i --) {
            if((id | (1 << i)) > n) continue;
            if(a[id | (1 << i)] < x) {
                x -= a[id | (1 << i)];
                id |= (1 << i);
            }
        }
        return id;
    }
};

int main() {
    int n;
    cin >> n;
    fenwick_tree<int> fw(N);
    for(int i = 1; i < N; i ++) fw.add(i, 1);
    for(int i = 0; i < n; i ++) {
        int a, b;
        cin >> a >> b;
        int id1 = fw.lower_bound(a);
        if(fw.sum(0, N) > b + 1) {
            int id2 = fw.lower_bound(b + 1);
            fw.add(id1, 1);
            fw.add(id2, -1);
        } else {
            fw.add(id1, 1);
        }
    }
    int q; cin >> q;
    for(int i = 0; i < q; i ++) {
        int x; cin >> x;
        cout << fw.sum(0, x + 1) << endl;
    }
    return 0;
}

int lower_bound(T x) {
        int le = 0, ri = N;
        while(ri - le > 1) {
            int mid = (ri + le) / 2;
            if(sum(0, mid) >= x) {
                ri = mid;
            } else {
                le = mid;
            }
        }
        return le;
    }
